test('projectComposition 서로 다른 관측 시점의 같은 ACK ID는 execution scope를 보존',async()=>{
 const f=fixture(),a=observationRows(),b=observationRows(1000);for(const ack of[b.a1,b.a2]){const old=ack.id;ack.id=a.a1.id;for(const r of b.t('execution_observation_results'))if(r.ack_id===old&&r.ack_version===ack.version)r.ack_id=ack.id;b.rebindAck(ack);}
 f.state.beforeAuth=n=>{if(n===32){for(const table of Object.keys(a.tables))f.tables[table]=[...clone(a.t(table)),...clone(b.t(table))];}if(n===34){for(const table of Object.keys(a.tables))f.tables[table]=[];}};
 const r=await f.run(),acks=r.references.filter((v:any)=>v.namespace==='ACK'&&v.ref.id===a.a1.id);assert.equal(acks.length,4);assert.equal(new Set(acks.map((v:any)=>v.scope.executionId)).size,2);assert.equal(r.components.find((c:any)=>c.name==='Observation').rowCounts.observationResults,6);assert.equal(r.atomicSnapshotVerified,false);
});
